def count_Substrings(s):
    """
    Given a string s, count the number of substrings with the sum of digits equal to their length.
    Example:
    assert count_Substrings('112112') == 6
    """
    count = 0
    for i in range(len(s)):
        for j in range(i, len(s)):
            sub = s[i:j+1]
            digit_sum = 0
            for char in sub:
                if char.isdigit():
                    digit_sum += int(char)
            if digit_sum == len(sub):
                count += 1
    return count
```

