def is_undulating(number):
    """
    Check whether the given number is undulating or not.
    A number is undulating if its digits alternate between two values.
    For example, 1212121 is undulating because its digits alternate between 1 and 2.
    """
    num_str = str(number)
    if len(num_str) < 2:
        return False
    first_digit = int(num_str[0])
    second_digit = int(num_str[1])
    for i in range(1, len(num_str)):
        if i % 2 == 0:
            if int(num_str[i]) != first_digit:
                return False
        else:
            if int(num_str[i]) != second_digit:
                return False
    return True
```

