def count_bidirectional(pairs):
    """
    Counts the number of bidirectional tuple pairs in a list.

    Args:
        pairs: A list of tuples.

    Returns:
        The number of bidirectional tuple pairs.
    """
    counts = {}
    for pair in pairs:
        if pair in counts:
            counts[pair] += 1
        else:
            counts[pair] = 1

    bidirectional_count = 0
    for pair, count in counts.items():
        if count % 2 == 0:
            bidirectional_count += count // 2

    return bidirectional_count
